class CompteBancaire {
  #solde = 0; // privé : inaccessible depuis l'extérieur

  deposer(montant) {
    if (montant <= 0) throw new Error('Montant invalide');
    this.#solde += montant;
  }

  get solde() { return this.#solde; } // accès contrôlé en lecture
}

class Animal {
  parler() { return '...'; }
}
class Chien extends Animal {
  parler() { return 'Wouf !'; }
}
class Chat extends Animal {
  parler() { return 'Miaou !'; }
}

[new Chien(), new Chat()].forEach((a) => console.log(a.parler())); // polymorphisme

// Héritage rigide :
class CanardRobot extends Canard { voler() { /* moteur */ } }

// Composition flexible :
class Canard {
  constructor(comportementVol) { this.comportementVol = comportementVol; }
  voler() { return this.comportementVol.voler(); }
}
const canardRobot = new Canard({ voler: () => 'vole avec un moteur' });

// Impure, mute le tableau original :
function ajouterImpure(arr, x) { arr.push(x); return arr; }

// Pure, ne modifie rien, retourne un nouveau tableau :
function ajouterPure(arr, x) { return [...arr, x]; }

// Piège : la copie "pure" n'est que superficielle (shallow) !
function ajouterPureButPiege(liste, obj) { const copie = [...liste]; copie[0].nom = 'modifié'; return copie; }
